package com.tarjs.app

import android.content.Context
import android.graphics.Color
import android.net.Uri
import androidx.test.core.app.ApplicationProvider
import androidx.compose.ui.graphics.asAndroidBitmap
import androidx.test.ext.junit.runners.AndroidJUnit4
import com.tarjs.app.core.MediaResolver
import java.io.File
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertTrue
import org.junit.Test
import org.junit.runner.RunWith
import org.robolectric.annotation.Config
import org.robolectric.annotation.GraphicsMode

/**
 * Real-bytes media decoding: synthetic PNG fixtures (no user data) are decoded through
 * the exact production thumbnail path used by gallery tiles and chat bubbles.
 */
@RunWith(AndroidJUnit4::class)
@Config(sdk = [34])
@GraphicsMode(GraphicsMode.Mode.NATIVE)
class MediaDecodingTest {

    private fun fixture(name: String, b64: String): File {
        val dir = File(ApplicationProvider.getApplicationContext<Context>().cacheDir, "media-fixture").apply { mkdirs() }
        return File(dir, name).apply { writeBytes(android.util.Base64.decode(b64, android.util.Base64.DEFAULT)) }
    }

    @Test
    fun thumbnailDecodeProducesRealPixels() {
        val context = ApplicationProvider.getApplicationContext<Context>()
        val file = fixture("half-half.png", SMALL_PNG_B64)
        val bitmap = decodeSampledBitmap(context, Uri.fromFile(file), 480)
        assertNotNull("production thumbnail decode returned null", bitmap)
        val android = bitmap!!.asAndroidBitmap()
        assertEquals(120, android.width)
        assertEquals(90, android.height)
        val left = android.getPixel(10, 45)
        val right = android.getPixel(110, 45)
        assertTrue("left half must decode red, got $left", Color.red(left) > 180 && Color.blue(left) < 80)
        assertTrue("right half must decode blue, got $right", Color.blue(right) > 180 && Color.red(right) < 80)
    }

    @Test
    fun thumbnailDecodeSamplesLargeImagesDown() {
        val context = ApplicationProvider.getApplicationContext<Context>()
        val file = fixture("large.png", LARGE_PNG_B64)
        val bitmap = decodeSampledBitmap(context, Uri.fromFile(file), 480)
        assertNotNull(bitmap)
        val w = bitmap!!.width
        val h = bitmap.height
        assertTrue("expected downsample from 1200x900, got $w x $h", w <= 600 && h <= 450)
        assertEquals(4.0 / 3.0, w.toDouble() / h.toDouble(), 0.01)
    }

    @Test
    fun inspectMediaReadsRealDimensions() {
        val context = ApplicationProvider.getApplicationContext<Context>()
        val dir = File(context.cacheDir, "media-fixture").apply { mkdirs() }
        fixture("half-half.png", SMALL_PNG_B64)
        val meta = MediaResolver(context.cacheDir).inspectMedia(dir, "half-half.png")
        assertNotNull(meta)
        assertEquals("photo", meta!!.kind)
        assertEquals(120, meta.width)
        assertEquals(90, meta.height)
        assertEquals("image/png", meta.mimeType)
    }

    private companion object {
        const val SMALL_PNG_B64 = ""
        const val LARGE_PNG_B64 = ""
    }
}
